//! Configured JMAP upload/download URLs, no server-origin widening.
use crate::*;
fn component(s:&str)->String{let mut out=String::new();for b in s.bytes(){if b.is_ascii_alphanumeric()||b"-._~".contains(&b){out.push(b as char)}else{out.push_str(&format!("%{b:02X}"))}}out}
pub fn upload_url(template:&str,m:&email::Mailbox)->Result<String,String>{email::Mailbox::new(&m.endpoint,&m.account,&m.mailbox,&m.credential)?;if !template.starts_with("https://")||template.len()>512||template.matches("{accountId}").count()!=1{return Err("Configure a JMAP upload URL template".into())}let url=template.replace("{accountId}",&component(&m.account));if url.contains(['{','}','\r','\n']){return Err("Unsupported upload URL variables".into())}Ok(url)}
pub fn upload(m:&email::Mailbox,template:&str,file:&Value,then:&str)->Result<Value,String>{let id=file["id"].as_str().ok_or("Choose a private file")?;let size=file["size"].as_u64().filter(|s|*s<=10485760).ok_or("Attachment exceeds10MiB")?;let _=size;let mime=file["mime"].as_str().ok_or("Missing file MIME")?;Ok(http::upload(&upload_url(template,m)?,id,mime,&m.credential,then))}
pub fn uploaded(m:&email::Mailbox,file:&Value,response:&Value)->Result<Value,String>{if ![200,201].contains(&response["status"].as_u64().unwrap_or(0)){return Err("Attachment upload failed; file retained locally".into())}let v=http::parse_json(response)?;if v["accountId"]!=m.account||v["size"]!=file["size"]||v["type"]!=file["mime"]{return Err("Upload account/type/size changed".into())}email_content::attachment(&json!({"blobId":v["blobId"],"name":file["name"],"type":v["type"],"size":v["size"]}))}
pub fn download_url(template:&str,m:&email::Mailbox,attachment:&Value)->Result<String,String>{let a=email_content::attachment(attachment)?;let mut url=template.to_string();if !url.starts_with("https://")||url.len()>1024{return Err("Configure an HTTPS download URL template".into())}for(k,v)in[("accountId",m.account.as_str()),("blobId",a["blobId"].as_str().unwrap()),("name",a["name"].as_str().unwrap()),("type",a["type"].as_str().unwrap())]{let key=format!("{{{k}}}");if url.matches(&key).count()!=1{return Err("Missing or repeated download URL variable".into())}url=url.replace(&key,&component(v));}if url.contains(['{','}','\r','\n']){return Err("Unsupported download template".into())}Ok(url)}
pub fn parse_mime(file:&str,then:&str)->Value{effect("mail.mime.parse",json!({"file":file}),then)}
#[cfg(test)]mod tests{use super::*;#[test]fn transfer_templates_encode_identifiers_and_correlate_upload(){let m=email::Mailbox::new("https://mail.example.org/jmap","a/b","drafts","aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa").unwrap();assert_eq!(upload_url("https://mail.example.org/upload/{accountId}",&m).unwrap(),"https://mail.example.org/upload/a%2Fb");let f=json!({"id":"a".repeat(32),"name":"demo.bin","mime":"application/octet-stream","size":3});let r=json!({"status":201,"text":json!({"accountId":"a/b","blobId":"server","type":"application/octet-stream","size":3}).to_string()});assert_eq!(uploaded(&m,&f,&r).unwrap()["blobId"],"server");let mut bad=f;bad["size"]=json!(4);assert!(uploaded(&m,&bad,&r).is_err());}}
